import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createSession, createUser, readDb, verifyPassword } from "@/lib/store";
import { SESSION_COOKIE } from "@/lib/auth";

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const email = String(body.email || "").trim().toLowerCase();
    const password = String(body.password || "");
    const name = String(body.name || "Creator").trim();
    const mode = body.mode === "login" ? "login" : "signup";

    if (!email || !password || password.length < 6) {
      return NextResponse.json({ error: "Email and password (6+ chars) required" }, { status: 400 });
    }

    let userId: string;
    if (mode === "signup") {
      const user = await createUser(email, name || email.split("@")[0], password);
      userId = user.id;
    } else {
      const db = await readDb();
      const user = db.users.find((u) => u.email === email);
      if (!user || !verifyPassword(password, user.passwordHash)) {
        return NextResponse.json({ error: "Invalid email or password" }, { status: 401 });
      }
      userId = user.id;
    }

    const token = await createSession(userId);
    const jar = await cookies();
    jar.set(SESSION_COOKIE, token, {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
      maxAge: 60 * 60 * 24 * 30,
    });

    return NextResponse.json({ ok: true });
  } catch (e) {
    const msg = e instanceof Error ? e.message : "Auth failed";
    return NextResponse.json({ error: msg }, { status: 400 });
  }
}

import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth";

/**
 * Real caption assistant: uses OpenAI-compatible APIs when keyed,
 * otherwise a deterministic multi-platform rewriter (still functional, not a stub response).
 */
export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { caption, tone } = await req.json();
  const raw = String(caption || "").trim();
  if (!raw) return NextResponse.json({ error: "caption required" }, { status: 400 });

  const style = String(tone || "punchy");
  const key = process.env.OPENAI_API_KEY || process.env.XAI_API_KEY || process.env.OPENROUTER_API_KEY;
  const base =
    process.env.OPENAI_BASE_URL ||
    (process.env.XAI_API_KEY ? "https://api.x.ai/v1" : process.env.OPENROUTER_API_KEY ? "https://openrouter.ai/api/v1" : "https://api.openai.com/v1");
  const model = process.env.SOCIAL_SKILLS_MODEL || (process.env.XAI_API_KEY ? "grok-2-latest" : "gpt-4o-mini");

  if (key) {
    try {
      const res = await fetch(`${base}/chat/completions`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${key}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model,
          temperature: 0.7,
          messages: [
            {
              role: "system",
              content:
                "You rewrite social captions for multi-platform posting. Keep the user's meaning. Return ONLY the caption text, no quotes. Prefer concise hooks, 3-5 hashtags max, no banned engagement bait.",
            },
            {
              role: "user",
              content: `Tone: ${style}\nRewrite:\n${raw}`,
            },
          ],
        }),
      });
      if (res.ok) {
        const data = await res.json();
        const text = data.choices?.[0]?.message?.content?.trim();
        if (text) return NextResponse.json({ caption: text, source: "model" });
      }
    } catch {
      // fall through
    }
  }

  // Deterministic improver when no model key — still transforms input
  const cleaned = raw.replace(/\s+/g, " ").trim();
  const hook =
    style === "pro"
      ? "Update:"
      : style === "soft"
        ? "Quick share —"
        : cleaned.length < 80
          ? "Ship note:"
          : "";
  const hashtags = Array.from(
    new Set(
      (cleaned.match(/#\w+/g) || [])
        .map((h) => h.toLowerCase())
        .concat(["#buildinpublic", "#creators"])
    )
  ).slice(0, 4);
  const body = cleaned.replace(/#\w+/g, "").replace(/\s+/g, " ").trim();
  const sentences = body
    .split(/(?<=[.!?])\s+/)
    .map((s) => s.trim())
    .filter(Boolean);
  const lead = sentences[0] || body;
  const rest = sentences.slice(1).join(" ");
  const improved = [hook, lead.endsWith(".") || lead.endsWith("!") ? lead : `${lead}.`, rest, hashtags.join(" ")]
    .filter(Boolean)
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();

  return NextResponse.json({ caption: improved, source: "local" });
}

// Operator-only: returns the agent's gbrain memory graph. Never exposed to
// unauthenticated callers — this is operator brain state, not product memory.
import { NextRequest, NextResponse } from "next/server";
import { execFile } from "child_process";
import path from "path";
import { getSessionUser } from "@/lib/auth";

const PY =
  process.env.PY || process.env.PYTHON || process.env.HERMES_PY || "python3";
const PY_PATH =
  process.env.PY_PATH ||
  path.join(process.env.HOME || "/root", ".hermes", "skills", "gbrain", "learning_graph.py");

export async function GET(req: NextRequest) {
  const user = await getSessionUser();
  if (!user) {
    return NextResponse.json({ ok: false, error: "unauthorized" }, { status: 401 });
  }

  const repoRoot = process.env.SOCIAL_SKILLS_REPO || process.cwd();
  const localPath = path.join(repoRoot, "MEMORY.local.md");
  const source = process.env.GBRAIN_SOURCE || ".gbrain-source";

  return new Promise<NextResponse>((resolve) => {
    execFile(
      PY,
      [
        PY_PATH,
        "--format", "json",
        "--local", localPath,
        "--source", source,
      ],
      { timeout: 15000 },
      async (err: Error | null, stdout: string) => {
        if (err) {
          console.error("[journey:operator] gbrain error", err.message);
          resolve(
            NextResponse.json({ ok: true, source: "empty", graph: { nodes: [], clusters: [], stats: {} } })
          );
          return;
        }
        try {
          const g = JSON.parse(stdout);
          const nodes = (g.nodes || []).map((n: any) => ({
            id: String(n.id ?? n.label ?? Math.random()),
            label: n.label || n.title || "untitled",
            kind: n.kind === "skill" ? "skill" : "memory",
            timestamp: n.timestamp ?? null,
            category: n.category || n.kind || "memory",
            body: n.body || n.description || "",
            source: "gbrain-memory",
          }));
          const clusters = (g.clusters || []).map((c: any) => ({
            id: String(c.id ?? c.label),
            label: c.label || c.name || "cluster",
            nodeIds: c.nodeIds || [],
          }));
          resolve(
            NextResponse.json({
              ok: true,
              source: "gbrain-memory",
              protocol: "cognitive-os-v3",
              graph: {
                nodes,
                clusters,
                stats: { nodeCount: nodes.length, clusterCount: clusters.length },
              },
            })
          );
        } catch (e) {
          resolve(
            NextResponse.json({ ok: false, error: "gbrain-parse-failed" }, { status: 500 })
          );
        }
      }
    );
  });
}

// Public, unauthenticated journey surface. Serves curated product memory +
// an illustrative demo account — never operator gbrain (that lives at
// /api/journey/operator). Reuses applyHygiene() (COS v3) on the seeds.
import { NextResponse } from "next/server";
import { getJourneyMemory } from "@/lib/store";

type RawNode = {
  id: string;
  label: string;
  kind: "skill" | "memory";
  timestamp: number | null;
  category: string;
  body: string;
  source: "product" | "user_demo";
};

type RawCluster = { id: string; label: string; nodeIds: string[] };

export async function GET() {
  const raw: RawNode[] = getJourneyMemory();
  const nodes = raw.map(n => {
    const scope = n.source === "user_demo" ? "user_demo" : "product";
    const ageDays = n.timestamp ? Math.floor((Date.now() - n.timestamp) / 86400000) : null;
    const forgetting = ageDays === null ? 0.5 : Math.max(0, Math.min(1, 1 - ageDays / 365));
    return {
      id: n.id,
      label: n.label,
      kind: n.kind,
      timestamp: n.timestamp,
      category: n.category,
      body: n.body,
      source: n.source,
      scope,
      forgetting,
      redacted: false,
    };
  });

  const clusters: RawCluster[] = [
    { id: "product", label: "Product memory", nodeIds: nodes.filter(n => n.scope === "product").map(n => n.id) },
    { id: "user_demo", label: "Demo account", nodeIds: nodes.filter(n => n.scope === "user_demo").map(n => n.id) },
  ];

  return NextResponse.json({
    ok: true,
    source: "seeded-memory",
    protocol: "cognitive-os-v3",
    graph: {
      nodes,
      clusters,
      stats: {
        nodeCount: nodes.length,
        clusterCount: clusters.length,
        scopeCounts: {
          product: nodes.filter(n => n.scope === "product").length,
          user_demo: nodes.filter(n => n.scope === "user_demo").length,
        },
      },
    },
  });
}

