}

/* Azure Neon Cyan Button (#00f0ff) */
.btn-azure {
  background: linear-gradient(135deg, #00f0ff 0%, #00b4d8 100%);
  color: #000000 !important;
  font-weight: 900;
  border-radius: 9999px;
  box-shadow: var(--plush-btn-azure-shadow);
