  border-radius: 9999px;
  padding: 4px 12px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* Pure Wu-Tang Yellow Metallic Gradient (#ffc800) */
.text-wutang-metallic {
  color: #d9a000 !important;
  font-weight: 900;
}

.text-azure-metallic {
  color: #0099b8 !important;
  font-weight: 900;
}

.text-azure-neon {
  color: #0088a3 !important;
}

/* Inside dark plush cards, keep Wu-Tang Yellow & Azure Neon bright (#ffc800 & #00f0ff) */
.plush-card .text-wutang-metallic {
  color: #ffc800 !important;
}

.plush-card .text-azure-metallic {
  color: #00f0ff !important;
}

.plush-card .text-azure-neon {
  color: #00f0ff !important;
}

/* Stylized Custom Scrollbar */
.custom-scrollbar::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.custom-scrollbar::-webkit-scrollbar-track {
  background: #020617;
  border-radius: 9999px;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
  background: #00f0ff;
  border-radius: 9999px;
  border: 2px solid #020617;
}

.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: #38bdf8;
}

/* Stylized Resize Handle */
textarea.custom-resize {
  resize: vertical;
}

textarea.custom-resize::-webkit-resizer {
  background-color: #00f0ff;
  border-radius: 4px;
}

/* Laser Flow Energy Animation */
@keyframes laserFlow {
  from {
    stroke-dashoffset: 24;
  }
  to {
    stroke-dashoffset: 0;
  }
}

.laser-pulse-active {
