"use client";

import React, { useEffect, useRef, useState } from "react";
import { PlatformColorLogo } from "@/components/PlatformColorLogo";
import type { Platform } from "@/lib/types";

type Phase = "type" | "select" | "preview" | "publish" | "done";

const FULL_CAPTION =
  "shipped a new per-platform transform engine\n\nx strips links automatically. ig validates media. threads gets a question hook. one desk, ten networks, zero tabs.";

const PLATFORMS_ORDER: { id: Platform; transform: string; adapted: string }[] = [
  { id: "twitter", transform: "link stripped", adapted: "shipped a new per-platform transform engine" },
  { id: "instagram", transform: "media attached", adapted: "shipped a new per-platform transform engine" },
  { id: "linkedin", transform: "full caption", adapted: "shipped a new per-platform transform engine with auto-transforms for every network" },
  { id: "threads", transform: "hook added", adapted: "ever wonder why cross-posting feels so manual? we fixed it." },
  { id: "bluesky", transform: "direct post", adapted: "shipped a new per-platform transform engine" },
];

const PHASE_DURATIONS = {
  type: 60,     // ms per character
  select: 280,  // ms per platform activation
  preview: 320, // ms per transform row
  publish: 400, // publish animation
  done: 2200,   // hold before loop
};

export function ComposeDeskMockup() {
  const [phase, setPhase] = useState<Phase>("type");
  const [charCount, setCharCount] = useState(0);
  const [activePlatforms, setActivePlatforms] = useState<Set<string>>(new Set());
  const [visibleTransforms, setVisibleTransforms] = useState(0);
  const [published, setPublished] = useState(false);
  const [cycle, setCycle] = useState(0);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  const clearTimers = () => {
    timers.current.forEach(clearTimeout);
    timers.current = [];
  };

  useEffect(() => {
    clearTimers();

    setCharCount(0);
    setActivePlatforms(new Set());
    setVisibleTransforms(0);
    setPublished(false);
    setPhase("type");

    const caption = FULL_CAPTION;
    const totalChars = caption.length;

    // Phase 1: Type caption
    for (let i = 1; i <= totalChars; i++) {
      const t = setTimeout(() => {
        setCharCount(i);
        if (i === totalChars) {
          const t2 = setTimeout(() => setPhase("select"), 400);
          timers.current.push(t2);
        }
      }, i * PHASE_DURATIONS.type);
      timers.current.push(t);
    }

    // Phase 2: Activate platforms one by one
    PLATFORMS_ORDER.forEach((p, idx) => {
      const delay = totalChars * PHASE_DURATIONS.type + 500 + idx * PHASE_DURATIONS.select;
      const t = setTimeout(() => {
        setActivePlatforms((prev) => new Set([...prev, p.id]));
        if (idx === PLATFORMS_ORDER.length - 1) {
          const t2 = setTimeout(() => setPhase("preview"), 500);
          timers.current.push(t2);
        }
      }, delay);
      timers.current.push(t);
    });

    // Phase 3: Populate transform rows
    const previewStart = totalChars * PHASE_DURATIONS.type + 500 + PLATFORMS_ORDER.length * PHASE_DURATIONS.select + 500;
    PLATFORMS_ORDER.forEach((_, idx) => {
      const t = setTimeout(() => {
        setVisibleTransforms(idx + 1);
        if (idx === PLATFORMS_ORDER.length - 1) {
          const t2 = setTimeout(() => setPhase("publish"), 500);
          timers.current.push(t2);
        }
      }, previewStart + idx * PHASE_DURATIONS.preview);
      timers.current.push(t);
    });

    // Phase 4: Publish
    const publishTime = previewStart + PLATFORMS_ORDER.length * PHASE_DURATIONS.preview + 500;
    const tPub = setTimeout(() => {
      setPublished(true);
      setPhase("done");
    }, publishTime);
    timers.current.push(tPub);

    // Phase 5: Loop
    const tLoop = setTimeout(() => {
      setCycle((c) => c + 1);
    }, publishTime + PHASE_DURATIONS.done);
    timers.current.push(tLoop);

    return clearTimers;
  }, [cycle]);

  const typedText = FULL_CAPTION.slice(0, charCount);
  const isTyping = phase === "type";
  const showCaret = phase === "type" || phase === "select";

  return (
    <div className="relative">
      {/* Glow behind card */}
      <div
        className="absolute -inset-4 rounded-3xl opacity-40 blur-3xl pointer-events-none"
        style={{
          background: "radial-gradient(ellipse at 30% 20%, var(--azure-neon), transparent 70%)",
        }}
        aria-hidden
      />

      {/* Main card */}
      <div className="plush-card p-6 md:p-8 space-y-6 overflow-hidden">
        {/* Window chrome header */}
        <div className="flex items-center justify-between border-b border-slate-700/60 pb-4">
          <div className="flex items-center gap-2">
            <span className="h-3 w-3 rounded-full bg-rose-500/80" />
            <span className="h-3 w-3 rounded-full bg-amber-500/80" />
            <span className="h-3 w-3 rounded-full bg-cyan-400/80" />
            <span className="ml-3 text-xs font-bold text-slate-300 font-mono">
              compose — socialskills.app
            </span>
          </div>
          {/* Live phase indicator */}
          <span
            className="flex items-center gap-1.5 text-[10px] font-extrabold uppercase tracking-wider px-3 py-1 rounded-full"
            style={{
              background: published ? "rgba(255, 200, 0, 0.15)" : "rgba(0, 240, 255, 0.15)",
              color: published ? "#ffc800" : "var(--azure-neon)",
              border: `1px solid ${published ? "rgba(255, 200, 0, 0.3)" : "rgba(0, 240, 255, 0.3)"}`,
            }}
          >
            <span
              className="inline-block h-1.5 w-1.5 rounded-full"
              style={{
                background: published ? "#ffc800" : "var(--azure-neon)",
                animation: "pulse-glow 1.5s ease-in-out infinite",
              }}
            />
            {published ? "published" : phase}
          </span>
        </div>

        {/* Compose Body */}
        <div className="space-y-5">
          {/* Stylized Text Area Input Box */}
          <div className="relative">
            <div
              className="custom-scrollbar custom-resize rounded-2xl p-4 text-sm font-medium leading-relaxed transition-all overflow-y-auto"
              style={{
                borderWidth: "2px",
                borderStyle: "solid",
                borderColor: isTyping ? "var(--azure-neon)" : "rgba(0, 240, 255, 0.3)",
                background: "#161920",
                color: "#ffffff",
                minHeight: "140px",
                maxHeight: "220px",
                boxShadow: isTyping
                  ? "0 0 20px rgba(0, 240, 255, 0.3), inset 0 2px 4px rgba(0,0,0,0.5)"
                  : "inset 0 2px 4px rgba(0,0,0,0.5)",
              }}
            >
              {typedText.split("\n").map((line, i, arr) => (
                <span key={i} className="text-white font-medium">
                  {line}
                  {i < arr.length - 1 && <br />}
                </span>
              ))}
              {showCaret && (
                <span
                  className="ml-0.5 inline-block h-4 w-0.5 align-middle bg-azure-neon animate-pulse"
                  style={{ background: "var(--azure-neon)" }}
                />
              )}

              {/* Media attachment badge */}
              {charCount > 40 && (
                <div
                  className="mt-4 flex items-center gap-3 rounded-xl p-3"
                  style={{
                    background: "#20242e",
                    border: "1px solid rgba(255, 255, 255, 0.1)",
                  }}
                >
                  <div
                    className="flex h-10 w-10 items-center justify-center rounded-lg text-black font-black"
                    style={{ background: "var(--azure-metallic)" }}
                  >
                    IMG
                  </div>
                  <div className="flex-1">
                    <p className="text-xs font-extrabold text-white">launch-photo.png</p>
                    <p className="text-[10px] text-slate-300">attached for IG, TikTok, YouTube, Pin</p>
                  </div>
                  <span
                    className="rounded-full px-2.5 py-0.5 text-[10px] font-black"
                    style={{ background: "rgba(0, 240, 255, 0.2)", color: "#00f0ff" }}
                  >
                    READY
                  </span>
                </div>
              )}
            </div>
          </div>

          {/* Toolbar: add media + char count */}
          <div className="flex items-center justify-between">
            <button className="btn-dark text-xs px-3.5 py-1.5 font-bold flex items-center gap-1.5">
              <span>+ Add media</span>
            </button>
            <span
              className="text-xs font-black font-mono"
              style={{ color: charCount > 0 ? "var(--azure-neon)" : "#94a3b8" }}
            >
              {charCount} / 2200 chars
            </span>
          </div>

          {/* Platform selector */}
          <div>
            <p className="mb-2 text-xs font-extrabold uppercase tracking-wider text-slate-300">
              Destinations
            </p>
            <div className="flex flex-wrap gap-2.5">
              {PLATFORMS_ORDER.map((p) => {
                const isActive = activePlatforms.has(p.id);
                return (
                  <div
                    key={p.id}
                    className="relative flex items-center justify-center rounded-xl p-2.5 transition-all duration-300"
                    style={{
                      borderWidth: "2px",
                      borderStyle: "solid",
                      borderColor: isActive ? "var(--azure-neon)" : "rgba(255, 255, 255, 0.1)",
                      background: isActive ? "rgba(0, 240, 255, 0.15)" : "#020617",
                      transform: isActive ? "scale(1.05)" : "scale(1)",
                      opacity: isActive ? 1 : 0.5,
                    }}
                  >
                    <PlatformColorLogo id={p.id} className="h-6 w-6" />
                    {isActive && (
                      <span className="absolute -right-1 -top-1 flex h-4 w-4 items-center justify-center rounded-full bg-cyan-400 text-black text-[9px] font-black">
                        ✓
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Per-platform transform preview */}
          {phase !== "type" && phase !== "select" && (
            <div className="space-y-2 pt-2 border-t border-slate-700/50">
              <p className="text-xs font-extrabold uppercase tracking-wider text-slate-300 mb-2">
                Per-Platform Adaptations
              </p>
              <div className="space-y-2">
                {PLATFORMS_ORDER.slice(0, visibleTransforms).map((p) => (
                  <div
                    key={p.id}
                    className="flex items-center gap-3 rounded-xl p-3"
                    style={{
                      background: "#0f172a",
                      border: "1px solid rgba(255, 255, 255, 0.1)",
                    }}
                  >
                    <PlatformColorLogo id={p.id} className="h-5 w-5 shrink-0" />
                    <div className="min-w-0 flex-1">
                      <span className="text-[10px] font-bold text-azure-neon uppercase tracking-wider mr-2">
                        [{p.transform}]
                      </span>
                      <span className="text-xs text-slate-200 font-medium truncate">{p.adapted}</span>
                    </div>
                    {published && <span className="text-xs font-black text-cyan-400">✓</span>}
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Publish bar */}
          <div className="flex items-center justify-between border-t border-slate-700/60 pt-4">
            <span className="text-xs font-bold text-slate-300">
              {published
                ? "5 accounts published successfully"
                : activePlatforms.size > 0
                  ? `${activePlatforms.size} accounts ready`
                  : "select destinations"}
            </span>
            <button
              className={published ? "btn-dark px-6 py-2.5 text-xs font-black" : "btn-wutang px-6 py-2.5 text-xs font-black"}
            >
              {published ? "Published ✓" : phase === "publish" ? "Publishing..." : `Publish to ${activePlatforms.size || 5}`}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import type { MediaAsset, Platform, PlatformOverride, PlatformResult, Post, SocialAccount } from "@/lib/types";
import { PLATFORMS, platformMeta } from "@/lib/platforms";
import { PlatformColorLogo } from "@/components/PlatformColorLogo";
import { AccountManager } from "./AccountManager";

type Me = {
  user: { id: string; email: string; name: string };
  accounts: SocialAccount[];
  posts: Post[];
  media: MediaAsset[];
};

function statusBadge(status: Post["status"]) {
  const map: Record<Post["status"], string> = {
    draft: "badge-muted",
    scheduled: "badge-warn",
    processing: "badge-warn",
    posted: "badge-ok",
    failed: "badge-bad",
    partial: "badge-warn",
  };
  return <span className={`badge ${map[status]}`}>{status}</span>;
}

function defaultScheduleLocal() {
  const d = new Date(Date.now() + 60 * 60 * 1000);
  d.setSeconds(0, 0);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export function DashboardApp() {
  const [me, setMe] = useState<Me | null>(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [caption, setCaption] = useState("Shipped today: one caption, every network. No more tab hopping.");
  const [selected, setSelected] = useState<number[]>([]);
  const [mediaIds, setMediaIds] = useState<string[]>([]);
  const [scheduleMode, setScheduleMode] = useState<"now" | "schedule" | "draft">("now");
  const [scheduledAt, setScheduledAt] = useState(defaultScheduleLocal);
  const [lastResults, setLastResults] = useState<PlatformResult[] | null>(null);
  const [lastPostId, setLastPostId] = useState<string | null>(null);
  const [tab, setTab] = useState<"compose" | "posts" | "accounts">("compose");
  const [showTips, setShowTips] = useState(false);
  const [showOverrides, setShowOverrides] = useState(false);
  const [overrides, setOverrides] = useState<Partial<Record<Platform, PlatformOverride>>>({});
  const [syncingPostId, setSyncingPostId] = useState<string | null>(null);
  const [showAccountModal, setShowAccountModal] = useState(false);

  async function refresh() {
    const res = await fetch("/api/me");
    if (!res.ok) {
      window.location.href = "/login";
      return;
    }
    const data = (await res.json()) as Me;
    setMe(data);
    setSelected((prev) => {
      if (prev.length) return prev;
      return data.accounts.filter((a) => a.connected).slice(0, 4).map((a) => a.id);
    });
    setLoading(false);
  }

  useEffect(() => {
    refresh().catch(() => setError("Failed to load"));
    try {
      setShowTips(localStorage.getItem("ss_tips_done") !== "1");
    } catch {
      setShowTips(true);
    }
  }, []);

  const accountsById = useMemo(() => {
    const m = new Map<number, SocialAccount>();
    me?.accounts.forEach((a) => m.set(a.id, a));
    return m;
  }, [me]);

  const selectedAccounts = useMemo(
    () => (me?.accounts || []).filter((a) => selected.includes(a.id)),
    [me, selected]
  );

  // ponytail: prune overrides for deselected platforms via derivation, not an
  // effect (setState-in-effect triggers cascading renders). The raw `overrides`
  // state stays as-authored; `effectiveOverrides` is what we render and submit.
  const effectiveOverrides = useMemo(() => {
    const selectedPlatforms = new Set(selectedAccounts.map((a) => a.platform));
    const next: Partial<Record<Platform, PlatformOverride>> = {};
    for (const [k, v] of Object.entries(overrides)) {
      if (selectedPlatforms.has(k as Platform) && v) {
        next[k as Platform] = v;
      }
    }
    return next;
  }, [overrides, selectedAccounts]);

  const mediaRequiredMissing = useMemo(() => {
    if (mediaIds.length) return [] as string[];
    return selectedAccounts
      .filter((a) => platformMeta(a.platform).needsMedia)
      .map((a) => platformMeta(a.platform).label);
  }, [selectedAccounts, mediaIds]);

  function toggleAccount(id: number) {
    setSelected((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  }

  function selectAll() {
    if (!me) return;
    setSelected(me.accounts.filter((a) => a.connected).map((a) => a.id));
  }

  function selectCore() {
    if (!me) return;
    const core = new Set(["twitter", "instagram", "tiktok", "linkedin"]);
    setSelected(me.accounts.filter((a) => core.has(a.platform)).map((a) => a.id));
  }

  async function onUpload(file: File) {
    setBusy(true);
    setError("");
    try {
      const fd = new FormData();
      fd.set("file", file);
      const res = await fetch("/api/upload", { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Upload failed");
      setMediaIds((ids) => [...ids, data.media.id]);
      setSuccess(`Uploaded ${data.media.name}`);
      await refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Upload failed");
    } finally {
      setBusy(false);
    }
  }

  async function improveCaption() {
    setBusy(true);
    setError("");
    try {
      const res = await fetch("/api/caption", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ caption, tone: "punchy" }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Rewrite failed");
      setCaption(data.caption);
      setSuccess(data.source === "model" ? "Caption improved with AI" : "Caption tightened");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Rewrite failed");
    } finally {
      setBusy(false);
    }
  }

  async function submit() {
    setBusy(true);
    setError("");
    setSuccess("");
    setLastResults(null);
    try {
      if (!selected.length) throw new Error("Pick at least one account");
      if (scheduleMode === "now" && mediaRequiredMissing.length && !mediaIds.length) {
        // still allow — server returns partial; warn clearly
        setSuccess(`Heads up: ${mediaRequiredMissing.join(", ")} need media — they'll fail until you upload.`);
      }
      const body: Record<string, unknown> = {
        caption,
        accountIds: selected,
        mediaIds,
        isDraft: scheduleMode === "draft",
      };
      if (Object.keys(effectiveOverrides).length > 0) {
        body.platformOverrides = effectiveOverrides;
      }
      if (scheduleMode === "schedule") {
        if (!scheduledAt) throw new Error("Pick a schedule time");
        body.scheduledAt = new Date(scheduledAt).toISOString();
      }
      const res = await fetch("/api/posts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Post failed");
      const post = data.post as Post;
      setLastResults(post.results || []);
      setLastPostId(post.id);
      setMediaIds([]);
      setOverrides({});
      setShowOverrides(false);
      await refresh();

      if (post.status === "draft") {
        setSuccess("Draft saved. Promote it anytime from Posts.");
        setTab("posts");
      } else if (post.status === "scheduled") {
        setSuccess(`Queued for ${new Date(post.scheduledAt!).toLocaleString()}`);
        setTab("posts");
      } else {
        const ok = (post.results || []).filter((r) => r.success).length;
        const total = (post.results || []).length;
        setSuccess(`Published to ${ok}/${total} accounts`);
        // stay on compose with results panel visible via lastResults; also switch for clarity
        setTab("posts");
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : "Post failed");
    } finally {
      setBusy(false);
    }
  }

  async function removePost(id: string) {
    if (!confirm("Delete this post?")) return;
    const res = await fetch(`/api/posts?id=${encodeURIComponent(id)}`, { method: "DELETE" });
    const data = await res.json();
    if (!res.ok) {
      setError(data.error || "Delete failed");
      return;
    }
    setSuccess("Post deleted");
    await refresh();
  }

  async function syncMetrics(postId: string) {
    setBusy(true);
    setError("");
    setSyncingPostId(postId);
    try {
      const res = await fetch(`/api/posts/analytics?post_id=${encodeURIComponent(postId)}`, {
        method: "POST",
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Sync failed");
      await refresh();
      setSuccess(data.synced > 0 ? `Synced ${data.synced} new result(s)` : "Metrics already up to date");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Sync failed");
    } finally {
      setBusy(false);
      setSyncingPostId(null);
    }
  }

  async function logout() {
    await fetch("/api/auth/logout", { method: "POST" });
    window.location.href = "/";
  }

  function dismissTips() {
    try {
      localStorage.setItem("ss_tips_done", "1");
    } catch {
      /* ignore */
    }
    setShowTips(false);
  }

  if (loading || !me) {
    return (
      <div className="container-page py-20 text-center text-muted">
        Warming up your Social Skills desk…
      </div>
    );
  }

  const mediaMap = new Map(me.media.map((m) => [m.id, m]));
  const postedCount = me.posts.filter((p) => p.status === "posted" || p.status === "partial").length;
  const scheduledCount = me.posts.filter((p) => p.status === "scheduled").length;

  return (
    <div style={{ background: "var(--bg-page-gradient)", color: "#0f172a", minHeight: "100vh" }} className="min-h-screen flex flex-col">
      <header className="border-b border-slate-300/60 bg-slate-900 text-white">
        <div className="container-page flex h-16 items-center justify-between">
          <a href="/" className="flex items-center gap-2 font-black text-white">
            <span className="font-black text-wutang-metallic text-lg">S/</span> social.skills
          </a>
          <div className="flex items-center gap-3 text-sm">
            <div className="hidden text-right sm:block">
              <div className="font-semibold text-ink">{me.user.name}</div>
              <div className="text-xs text-muted">
                {postedCount} live · {scheduledCount} queued
              </div>
            </div>
            <button className="btn btn-ghost" onClick={logout} type="button">
              Log out
            </button>
          </div>
        </div>
      </header>

      <div className="container-page py-8">
        <div className="mb-6 flex flex-wrap items-end justify-between gap-4">
          <div>
            <h1 className="text-2xl font-black text-slate-900 md:text-3xl">Publishing Desk</h1>
            <p className="mt-1 text-sm font-bold text-slate-800">Caption &rarr; accounts &rarr; go. That&apos;s the whole skill.</p>
          </div>
          <div className="flex gap-2 rounded-2xl border border-slate-700 bg-slate-900 p-1.5 shadow-sm">
            {(["compose", "posts", "accounts"] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setTab(t)}
                className={`rounded-xl px-4 py-2 text-xs font-black capitalize transition-all ${tab === t ? "btn-wutang" : "text-slate-300 hover:text-white"}`}
              >
                {t}
              </button>
            ))}
          </div>
        </div>

        {showTips && me.accounts.length > 0 && (
          <div className="card mb-4 border-primary/30 bg-primary-soft/40 p-4 md:p-5">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <div className="font-semibold text-ink">First 60 seconds</div>
                <ol className="mt-2 list-decimal space-y-1 pl-5 text-sm text-muted">
                  <li>Select the accounts you want to post to (or hit All)</li>
                  <li>Tweak the caption — or tap Improve caption</li>
                  <li>Upload a clip if IG / TikTok / YouTube are selected</li>
                  <li>Post now and read the per-platform results</li>
                </ol>
              </div>
              <button type="button" className="btn btn-ghost" onClick={dismissTips}>
                Got it
              </button>
            </div>
          </div>
        )}

        {error ? (
          <div className="mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" role="alert">
            {error}
          </div>
        ) : null}
        {success ? (
          <div className="mb-4 rounded-xl border border-cyan-500/30 bg-cyan-500/10 px-4 py-3 text-sm text-cyan-200" role="status">
            {success}
            {lastPostId && tab === "compose" ? (
              <button type="button" className="ml-2 font-semibold underline" onClick={() => setTab("posts")}>
                View posts
              </button>
            ) : null}
          </div>
        ) : null}

        {tab === "compose" && (
          <div className="grid gap-6 lg:grid-cols-[1.4fr_1fr]">
            <section className="card p-5 md:p-6">
              <div className="mb-3 flex items-center justify-between gap-3">
                <h2 className="text-lg font-semibold text-ink">Compose</h2>
                <button type="button" className="btn btn-ghost" disabled={busy || !caption.trim()} onClick={improveCaption}>
                  Improve caption
                </button>
              </div>
              <textarea
                className="textarea mb-2"
                value={caption}
                onChange={(e) => setCaption(e.target.value)}
                placeholder="Write your caption…"
                maxLength={5000}
              />
              <div className="mb-4 flex justify-between text-xs text-muted">
                <span>{caption.length} chars</span>
                <span>{selected.length} accounts selected</span>
              </div>

              <div className="mb-4 flex flex-wrap items-center gap-3">
                <label className="btn btn-ghost cursor-pointer">
                  {busy ? "Uploading…" : "Upload media"}
                  <input
                    type="file"
                    accept="image/*,video/mp4,video/quicktime,.pdf"
                    className="hidden"
                    disabled={busy}
                    onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) onUpload(f);
                      e.currentTarget.value = "";
                    }}
                  />
                </label>
                {mediaIds.length === 0 ? (
                  <span className="text-xs text-muted">PNG/JPG/MP4 · required for IG, TikTok, YT, Pinterest</span>
                ) : (
                  mediaIds.map((id) => {
                    const m = mediaMap.get(id);
                    return (
                      <span key={id} className="badge">
                        {m?.name || id}
                        <button type="button" className="ml-1" aria-label="Remove media" onClick={() => setMediaIds((x) => x.filter((i) => i !== id))}>
                          ×
                        </button>
                      </span>
                    );
                  })
                )}
              </div>

              {mediaRequiredMissing.length > 0 && (
                <div className="mb-4 rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-900">
                  {mediaRequiredMissing.join(", ")} need media for a clean publish.
                </div>
              )}

              {selectedAccounts.length > 0 && (
                <div className="mb-4">
                  <button
                    type="button"
                    className="flex w-full items-center justify-between rounded-lg border border-line bg-white px-3 py-2 text-sm font-semibold text-ink"
                    onClick={() => setShowOverrides((v) => !v)}
                    aria-expanded={showOverrides}
                  >
                    <span>
                      Per-platform tweaks
                      {Object.keys(effectiveOverrides).length > 0
                        ? ` · ${Object.keys(effectiveOverrides).length} overridden`
                        : ""}
                    </span>
                    <span className="text-xs text-muted">{showOverrides ? "hide" : "show"}</span>
                  </button>
                  {showOverrides && (
                    <div className="mt-2 grid gap-3">
                      <p className="text-xs text-muted">
                        Override the caption or title for a specific platform. Empty fields fall back to the
                        base caption above. Shape mirrors Post Bridge&apos;s <code>platform_configurations</code>.
                      </p>
                      {selectedAccounts.map((a) => {
                        const meta = platformMeta(a.platform);
                        const ov = effectiveOverrides[a.platform] || {};
                        const hasTitle = meta.hasTitle;
                        return (
                          <div key={a.id} className="rounded-lg border border-line bg-white p-3">
                            <div className="mb-2 flex items-center justify-between">
                              <span className="text-sm font-semibold text-ink">
                                {meta.label} <span className="text-muted">@{a.username}</span>
                              </span>
                              {(ov.caption !== undefined || ov.title !== undefined) && (
                                <button
                                  type="button"
                                  className="text-xs text-red-600"
                                  onClick={() =>
                                    setOverrides((prev) => {
                                      const next = { ...prev };
                                      delete next[a.platform];
                                      return next;
                                    })
                                  }
                                >
                                  reset
                                </button>
                              )}
                            </div>
                            {hasTitle && (
                              <label className="mb-2 block text-xs font-medium text-muted">
                                Title
                                <input
                                  type="text"
                                  className="input mt-1"
                                  placeholder={`Defaults to base caption (max 100)`}
                                  value={ov.title ?? ""}
                                  onChange={(e) =>
                                    setOverrides((prev) => ({
                                      ...prev,
                                      [a.platform]: { ...prev[a.platform], title: e.target.value },
                                    }))
                                  }
                                />
                              </label>
                            )}
                            <label className="block text-xs font-medium text-muted">
                              Caption
                              <textarea
                                className="textarea mt-1"
                                style={{ minHeight: 80 }}
                                placeholder={`Override caption · max ${meta.maxCaption}`}
                                maxLength={meta.maxCaption}
                                value={ov.caption ?? ""}
                                onChange={(e) =>
                                  setOverrides((prev) => ({
                                    ...prev,
                                    [a.platform]: { ...prev[a.platform], caption: e.target.value },
                                  }))
                                }
                              />
                            </label>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              )}

              <div className="mb-4 grid gap-3 sm:grid-cols-3">
                {(
                  [
                    ["now", "Post now", "Publish immediately"],
                    ["schedule", "Schedule", "Pick a time"],
                    ["draft", "Save draft", "Review later"],
                  ] as const
                ).map(([id, label, sub]) => (
                  <button
                    key={id}
                    type="button"
                    className={`platform-chip ${scheduleMode === id ? "active" : ""}`}
                    onClick={() => {
                      setScheduleMode(id);
                      if (id === "schedule" && !scheduledAt) setScheduledAt(defaultScheduleLocal());
                    }}
                  >
                    <div className="font-semibold text-ink">{label}</div>
                    <div className="text-xs text-muted">{sub}</div>
                  </button>
                ))}
              </div>

              {scheduleMode === "schedule" && (
                <label className="mb-4 block text-sm font-medium text-ink">
                  Go live at
                  <input
                    type="datetime-local"
                    className="input mt-1"
                    value={scheduledAt}
                    onChange={(e) => setScheduledAt(e.target.value)}
                  />
                </label>
              )}

              <button type="button" className="btn btn-primary w-full" disabled={busy || !selected.length} onClick={submit}>
                {busy
                  ? "Working…"
                  : scheduleMode === "now"
                    ? `Publish to ${selected.length} account${selected.length === 1 ? "" : "s"}`
                    : scheduleMode === "schedule"
                      ? "Add to queue"
                      : "Save draft"}
              </button>
              <p className="mt-3 text-xs text-muted">
                Local publisher validates each network (media rules, caption limits, X link stripping). Live OAuth publishers plug in when you connect real API keys.
              </p>
            </section>

            <section className="card p-5 md:p-6">
              <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
                <h2 className="text-lg font-semibold text-ink">Accounts</h2>
                <div className="flex gap-2 text-xs">
                  <button type="button" className="badge badge-muted" onClick={selectCore}>
                    Core 4
                  </button>
                  <button type="button" className="badge badge-muted" onClick={selectAll}>
                    All
                  </button>
                  <button type="button" className="badge badge-muted" onClick={() => setSelected([])}>
                    None
                  </button>
                </div>
              </div>
              <div className="grid max-h-[28rem] gap-2 overflow-y-auto pr-1">
                {me.accounts.map((a) => {
                  const meta = platformMeta(a.platform);
                  const active = selected.includes(a.id);
                  return (
                    <button key={a.id} type="button" className={`platform-chip ${active ? "active" : ""}`} onClick={() => toggleAccount(a.id)}>
                      <div className="flex items-center gap-3">
                        <PlatformColorLogo id={a.platform} className="h-9 w-9 shrink-0" />
                        <div className="min-w-0 text-left">
                          <div className="truncate font-semibold text-ink">@{a.username}</div>
                          <div className="text-xs text-muted">
                            {meta.label}
                            {meta.needsMedia ? " · media" : ""}
                            {meta.stripsLinks ? " · strips links" : ""}
                          </div>
                        </div>
                        <span className={`ml-auto text-xs font-semibold ${active ? "text-primary-dark" : "text-muted"}`}>
                          {active ? "on" : "off"}
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            </section>
          </div>
        )}

