globalStyles:
@import "tailwindcss";

:root {
  /* Sleek Obsidian Dark Studio Base */
  --bg-page: #0b0d14;
  --bg-page-gradient: linear-gradient(180deg, #0b0d14 0%, #0f131d 50%, #131722 100%);

  /* Deep Obsidian Slate Plush Cards */
  --bg-card: #151924;
  --bg-card-hover: #1c2232;
  --bg-surface: #1c2232;
  --bg-inset: #090b10;

  /* Text Colors */
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dark: #cbd5e1;

  /* PURE ELECTRIC WU-TANG YELLOW (#ffc800) */
  --wutang-yellow: #ffc800;
  --wutang-gradient: linear-gradient(135deg, #ffe033 0%, #ffc800 100%);
  --wutang-metallic: linear-gradient(180deg, #fff399 0%, #ffc800 100%);
  --wutang-glow: 0 0 25px rgba(255, 200, 0, 0.45);

  /* Electric Azure Neon Cyan Metallic (#00f0ff) */
  --azure-neon: #00f0ff;
  --azure-gradient: linear-gradient(135deg, #38bdf8 0%, #00f0ff 100%);
  --azure-metallic: linear-gradient(180deg, #a6fbff 0%, #00f0ff 100%);
  --azure-glow: 0 0 25px rgba(0, 240, 255, 0.45);

  /* Pixar Plushy & Lego 3D Shadows & Bevel Rims */
  --plush-card-shadow: 
    0 25px 50px -12px rgba(0, 0, 0, 0.5), 
    0 4px 16px rgba(0, 0, 0, 0.3),
    inset 0 1px 2px rgba(255, 255, 255, 0.1);

  --plush-btn-wutang-shadow: 
    0 10px 25px -4px rgba(255, 200, 0, 0.5),
    0 4px 10px rgba(0, 0, 0, 0.2);

  --plush-btn-azure-shadow: 
    0 10px 25px -4px rgba(0, 240, 255, 0.4),
    0 4px 10px rgba(0, 0, 0, 0.2);

  --plush-btn-dark-shadow: 
    0 8px 20px -4px rgba(0, 0, 0, 0.4);
}

html, body {
  background: var(--bg-page-gradient);
  background-color: var(--bg-page);
  color: #f8fafc;
  margin: 0;
  padding: 0;
  font-family: var(--font-geist-sans), system-ui, -apple-system, sans-serif;
  overflow-x: hidden;
}

h1, h2, h3 {
  font-weight: 900;
  letter-spacing: -0.03em;
}

/* Headings INSIDE dark .plush-card containers: PURE WHITE */
.plush-card h1, 
.plush-card h2, 
.plush-card h3 {
  color: #ffffff;
  text-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
}

/* Inside dark .plush-card containers (#0f172a), text is crisp pure white / light slate */
.plush-card {
  background: var(--bg-card);
  border-radius: 28px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: var(--plush-card-shadow);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  position: relative;
  color: #f8fafc;
}

.plush-card:hover {
  background: var(--bg-card-hover);
  border-color: rgba(255, 200, 0, 0.6);
  transform: translateY(-4px);
  box-shadow: 
    0 30px 60px -12px rgba(15, 23, 42, 0.4), 
    0 0 25px rgba(255, 200, 0, 0.35);
}

/* Crisp input styles */
input, textarea {
  color: #ffffff;
  background-color: #0f172a;
}

/* PURE WU-TANG YELLOW BUTTON (#ffc800) */
.btn-wutang {
  background: linear-gradient(135deg, #ffe033 0%, #ffc800 100%);
  color: #000000 !important;
  font-weight: 900;
  border-radius: 9999px;
  box-shadow: var(--plush-btn-wutang-shadow);
  transition: all 0.2s ease;
  border: 2px solid #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}

.btn-wutang:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 
    0 14px 30px -4px rgba(255, 200, 0, 0.6),
    0 0 25px rgba(255, 200, 0, 0.4);
  color: #000000 !important;
}

/* Azure Neon Cyan Button (#00f0ff) */
.btn-azure {
  background: linear-gradient(135deg, #00f0ff 0%, #00b4d8 100%);
  color: #000000 !important;
  font-weight: 900;
  border-radius: 9999px;
  box-shadow: var(--plush-btn-azure-shadow);
  transition: all 0.2s ease;
  border: 2px solid #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}

.btn-azure:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 
    0 14px 30px -4px rgba(0, 240, 255, 0.6),
    0 0 25px rgba(0, 240, 255, 0.4);
  color: #000000 !important;
}

/* Dark Plush Button */
.btn-dark {
  background: #0f172a;
  color: #ffffff !important;
  font-weight: 700;
  border-radius: 9999px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: var(--plush-btn-dark-shadow);
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}

.btn-dark:hover {
  background: #1e293b;
  border-color: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
  color: #ffffff !important;
}

/* Plush Badge Pills */
.plush-badge-wutang {
  background: rgba(255, 200, 0, 0.18);
  color: #b38b00 !important;
  border: 1.5px solid rgba(255, 200, 0, 0.5);
  border-radius: 9999px;
  padding: 4px 12px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.plush-badge-azure {
  background: rgba(0, 240, 255, 0.15);
  color: #007799 !important;
  border: 1.5px solid rgba(0, 240, 255, 0.5);
  border-radius: 9999px;
  padding: 4px 12px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* Pure Wu-Tang Yellow Metallic Gradient (#ffc800) */
.text-wutang-metallic {
  color: #d9a000 !important;
  font-weight: 900;
}

.text-azure-metallic {
  color: #0099b8 !important;
  font-weight: 900;
}

.text-azure-neon {
  color: #0088a3 !important;
}

/* Inside dark plush cards, keep Wu-Tang Yellow & Azure Neon bright (#ffc800 & #00f0ff) */
.plush-card .text-wutang-metallic {
  color: #ffc800 !important;
}

.plush-card .text-azure-metallic {
  color: #00f0ff !important;
}

.plush-card .text-azure-neon {
  color: #00f0ff !important;
}

/* Stylized Custom Scrollbar */
.custom-scrollbar::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.custom-scrollbar::-webkit-scrollbar-track {
  background: #020617;
  border-radius: 9999px;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
  background: #00f0ff;
  border-radius: 9999px;
  border: 2px solid #020617;
}

.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: #38bdf8;
}

/* Stylized Resize Handle */
textarea.custom-resize {
  resize: vertical;
}

textarea.custom-resize::-webkit-resizer {
  background-color: #00f0ff;
  border-radius: 4px;
}

/* Laser Flow Energy Animation */
@keyframes laserFlow {
  from {
    stroke-dashoffset: 24;
  }
  to {
    stroke-dashoffset: 0;
  }
}

.laser-pulse-active {
  stroke-dasharray: 8 6;
  animation: laserFlow 0.8s linear infinite;
}
